import { Schema, model } from 'mongoose';
const line = new Schema({ description: { type: String, required: true }, quantity: { type: Number, required: true, min: 0.001 }, unitPrice: { type: Number, required: true, min: 0 }, taxRate: { type: Number, required: true, min: 0, max: 100 } }, { _id: false });
export const InvoiceDraft = model('InvoiceDraft', new Schema({ clientName: { type: String, required: true }, clientTaxId: String, clientAddress: String, date: { type: String, required: true }, lines: { type: [line], required: true }, notes: String, subtotalCents: { type: Number, required: true }, taxCents: { type: Number, required: true }, totalCents: { type: Number, required: true }, archived: { type: Boolean, default: false } }, { timestamps: true }));
export const Expense = model('Expense', new Schema({ supplier: { type: String, required: true }, description: { type: String, required: true }, category: { type: String, required: true }, date: { type: String, required: true }, totalCents: { type: Number, required: true, min: 1 }, reference: String, paid: { type: Boolean, default: false }, archived: { type: Boolean, default: false } }, { timestamps: true }));
export const FinanceSettings = model('FinanceSettings', new Schema({ _id: { type: String, default: 'restaurant' }, legalName: String, taxId: String, address: String, email: String, phone: String, invoiceSeries: String, currentBillingSystem: String }, { timestamps: true }));
